-- Seeds the business dictionaries consumed by contract management and CRM forms.
-- The runtime read endpoint is authenticated-only (no dictionary:read required) and
-- returns ACTIVE items only, so business users can consume these without any grant.
-- Item values are the literal strings stored on business records; renaming a label
-- here would orphan historical data, so treat values as immutable once published.

ON DUPLICATE KEY UPDATE
    name = VALUES(name),
    description = VALUES(description),
    updated_at = UTC_TIMESTAMP(3);

ON DUPLICATE KEY UPDATE
    label = VALUES(label),
    item_value = VALUES(item_value),
    sort_order = VALUES(sort_order),
    updated_at = UTC_TIMESTAMP(3);
